CREATE INDEX command_issued ON commands(created_at);
ALTER TABLE orders ADD COLUMN legacy_production_zone TEXT;
WITH RECURSIVE names(id,name) AS (SELECT id,trim(replace(replace(replace(replace(json_extract(client_snapshot,'$.zone'),char(9),' '),char(10),' '),char(13),' '),char(160),' ')) FROM orders WHERE nullif(json_extract(client_snapshot,'$.zoneId'),'') IS NULL AND json_type(client_snapshot,'$.zone')='text' UNION ALL SELECT id,replace(name,'  ',' ') FROM names WHERE instr(name,'  ')>0), normalized AS (SELECT id,lower(replace(replace(replace(replace(replace(replace(replace(name,'Á','á'),'É','é'),'Í','í'),'Ó','ó'),'Ú','ú'),'Ü','ü'),'Ñ','ñ')) name_key FROM names WHERE name<>'' AND instr(name,'  ')=0) UPDATE orders SET legacy_production_zone=(SELECT CASE WHEN z.id IS NULL THEN 'legacy:' || n.name_key ELSE 'zone:' || z.id END FROM normalized n LEFT JOIN zones z ON z.name_key=n.name_key WHERE n.id=orders.id) WHERE id IN (SELECT id FROM normalized);
